36	/// Media dimension ceiling. Nothing decodes at this size — it exists so a
37	/// probe that reports garbage (or a hand-written project) cannot put a
38	/// number in the document that later overflows a texture allocation or
39	/// collapses `fit_scale` to zero.
40	const MEDIA_DIMENSION_MAX: u32 = 65536;
41	
42	/// The keys a media descriptor may carry: the spec §5.2 `media[]` element
43	/// MINUS `id`. Spelled out rather than derived from a serialized [`Media`],
44	/// because the point of the list is to NAME a misspelled key — serde would
45	/// silently drop `"widht"` and leave the user with a zero-width media.
46	/// `edit_relink.rs` reads it too, for a relink's probe (which may not carry
47	/// `color`: a relink keeps the media's Camera Log, spec §11 GR-16).
48	pub(crate) const MEDIA_KEYS: [&str; 13] = [
49	    "path",
50	    "bookmark",
51	    "kind",
52	    "duration",
53	    "width",
54	    "height",
55	    "fps",
56	    "has_video",
57	    "has_audio",
58	    "has_alpha",
59	    "original",
60	    "color",
61	    "cursor",
62	];
63	
64	// ---- helpers -------------------------------------------------------------
65	
66	/// Whether `clip` shows `media`. The three media-bound sources name an id;
67	/// text, shape and nest do not (spec §5.2) — a nest clip shows a GROUP, and
68	/// what that group references is asked of its own clips, which live in the
69	/// same id space and are swept alongside the timeline's.
70	fn uses_media(clip: &Clip, media: u32) -> bool {
71	    clip.source.media() == Some(media)
72	}
73	
74	/// The clips of a `with_clips` refusal, as English (deepening D2·3).
75	///
76	/// Both refusals that `with_clips` is the way past — a track that still
77	/// holds clips and a media a clip still shows — name the clips a caller
78	/// would otherwise have to ask for, so this is written once. At most three
79	/// ids are listed and the rest are a count: a media used by two hundred
80	/// clips would otherwise answer with a sentence nothing could read, and the
81	/// first three plus the total is everything the caller acts on.
82	/// Both callers ask only when they have at least one, and the empty arm is
83	/// here anyway: `split_last` rather than `some[..len - 1]`, because the
84	/// index form underflows on an empty slice and the crate's rule is that no
85	/// input may panic (`core/CLAUDE.md`, Errors). A third caller that forgets
86	/// the guard gets a poor sentence rather than a caught panic.
87	pub(crate) fn clip_list(ids: &[u32]) -> String {
88	    let named: Vec<String> = ids.iter().take(3).map(|id| id.to_string()).collect();
89	    let rest = ids.len().saturating_sub(named.len());
90	    match (named.split_last(), rest) {
91	        (None, _) => "no clips".to_string(),
92	        (Some((last, [])), 0) => format!("clip {last}"),
93	        (Some((last, front)), 0) => format!("clips {} and {last}", front.join(", ")),
94	        (Some(_), more) => format!("clips {} and {more} more", named.join(", ")),
95	    }
96	}
97	
98	/// A media's `original` as it is stored (spec §11 #228-O): the path
99	/// trimmed, and a blank bookmark dropped, for the reason `add_media` drops
100	/// a blank media bookmark. An empty path is left for `check_media_fields`
101	/// to refuse by name. `add_media`, a relink's probe and a media row
102	/// `paste` or `paste_attributes` appends (`edit_paste.rs`) all read it.
103	pub(crate) fn normalize_original(original: Option<MediaOriginal>) -> Option<MediaOriginal> {
104	    original.map(|given| MediaOriginal {
105	        path: given.path.trim().to_string(),
106	        bookmark: given.bookmark.filter(|b| !b.trim().is_empty()),
107	    })
108	}
109	
110	/// The checks a media record's fields must pass once the descriptor has
111	/// matched the schema — `add_media`'s, a relink probe's
112	/// (`edit_relink.rs`) and a pasted media row's that `paste` or
113	/// `paste_attributes` appends (`edit_paste.rs`), in one order and one set
114	/// of sentences: an empty
115	/// path, a `lut` row with a picture, sound or duration (`lut.rs`), a
116	/// negative duration, a media with pixels whose size or rate is not
117	/// usable, an original with an empty path, a `cursor` with an empty path or
118	/// on a media without a picture (`cursor_props.rs`, spec §11 CU-39).
119	pub(crate) fn check_media_fields(media: &Media) -> Result<(), String> {
120	    if media.path.trim().is_empty() {
121	        return Err("media path must not be empty".to_string());
122	    }
123	    crate::lut::check_lut_fields(media)?;
124	    if media.duration < 0 {
125	        return Err(format!(
126	            "media duration must not be negative, not {}",
127	            media.duration
128	        ));
129	    }
130	    // Size and rate are only meaningful for a media with pixels: an
131	    // audio file legitimately reports 0×0. A drawing media with a zero
132	    // dimension would make `fit_scale` and the frame recipe's
133	    // `source_size` meaningless.
134	    let draws = media.has_video || matches!(media.kind, MediaKind::Image);
135	    if draws {
136	        if media.width == 0 || media.height == 0 {
137	            return Err(format!(
138	                "a media with pixels must have a positive width and height, not {}x{}",
139	                media.width, media.height
140	            ));
141	        }
142	        if media.width > MEDIA_DIMENSION_MAX || media.height > MEDIA_DIMENSION_MAX {
143	            return Err(format!(
144	                "media dimensions must be at most {MEDIA_DIMENSION_MAX}, not {}x{}",
145	                media.width, media.height
146	            ));
147	        }
148	    }
149	    if media.has_video && !media.fps.is_valid() {
150	        return Err(format!(
151	            "a media with video must have a frame rate with non-zero terms, not [{}, {}]",
152	            media.fps.num, media.fps.den
153	        ));
154	    }
155	    if media
156	        .original
157	        .as_ref()
158	        .is_some_and(|original| original.path.trim().is_empty())
159	    {
160	        return Err("media original path must not be empty".to_string());
161	    }
162	    crate::cursor_props::check_media_cursor(media)
163	}
164	
165	// ---- the ops -------------------------------------------------------------
166	
167	impl Project {
168	    fn require_marker(&self, id: u32) -> Result<&Marker, String> {
169	        self.marker(id)
170	            .ok_or_else(|| format!("no marker with id {id}"))
171	    }
172	
173	    // ---- tracks ----------------------------------------------------------
174	
175	    /// Inserts a track at `index`, where 0 is the BACK-most (bottom) layer
176	    /// and `tracks.len()` is the front; `None` means the front, which is
177	    /// where a new layer goes (spec §6).
178	    ///
179	    /// The default name is `Track <count + 1>` — named by the count, not by
180	    /// the index, so inserting in the middle does not renumber the tracks
181	    /// above it under the user. A name of only whitespace is treated as
182	    /// absent. `Err` for an index past the end, or (through `finish`) for
183	    /// exceeding the track cap.
184	    pub fn add_track(&self, index: Option<usize>, name: Option<&str>) -> Result<Outcome, String> {
185	        let at = match index {
186	            None => self.tracks.len(),
187	            Some(given) if given <= self.tracks.len() => given,
188	            Some(given) => {
189	                return Err(format!(
190	                    "track index {given} is out of range (0..={})",
191	                    self.tracks.len()
192	                ))
193	            }
194	        };
195	
196	        let mut next = self.clone();
197	        let id = next.allocate_id();
198	        let name = name
199	            .map(str::trim)
200	            .filter(|given| !given.is_empty())
201	            .map(|given| given.to_string())
202	            .unwrap_or_else(|| next.next_track_name());
203	        next.tracks.insert(at, Track::ordinary(id, name));
204	        self.finish(next)
205	    }
206	
207	    /// Removes a track. Refuses on a track that still holds clips unless
208	    /// `with_clips`, which removes those clips with it, and refuses to
209	    /// remove the LAST track: a project always has somewhere to put a clip,
210	    /// and an empty track stack is a UI with nothing to drop onto.
211	    ///
212	    /// Both refusals carry their own sentence. The last-track one is asked
213	    /// FIRST, because `with_clips: true` is the way past the other and past
214	    /// this one it is not: a caller told about the clips would send it and
215	    /// be refused again.
216	    ///
217	    /// `Err` only for an unknown track.
218	    pub fn remove_track(&self, track: u32, with_clips: bool) -> Result<Outcome, String> {
219	        self.require_track(track)?;
220	        if self.tracks.len() <= 1 {
221	            return Ok(Outcome::Refused(format!(
222	                "track {track} is the only track left, and a project must always have one"
223	            )));
224	        }
225	        let held: Vec<u32> = self
226	            .clips
227	            .iter()
228	            .filter(|c| c.track == track)
229	            .map(|c| c.id)
230	            .collect();
231	        if !held.is_empty() && !with_clips {
232	            return Ok(Outcome::Refused(format!(
233	                "track {track} still holds {}; pass with_clips: true to remove the track \
234	                 and its clips",
235	                clip_list(&held)
236	            )));
237	        }
238	
239	        let mut next = self.clone();
240	        next.tracks.retain(|t| t.id != track);
241	        next.clips.retain(|c| c.track != track);
242	        self.finish(next)
243	    }
244	
245	    /// Moves a track to `index` in the stack (0 = back-most), sliding the
246	    /// tracks it passes over the other way — the layer reorder the timeline
247	    /// drag makes (spec §6).
248	    ///
249	    /// `Err` for an unknown track or an index past the end; an identity
250	    /// when the track is already there.
251	    pub fn move_track(&self, track: u32, index: usize) -> Result<Outcome, String> {
252	        let from = self.require_track_index(track)?;
253	        if index >= self.tracks.len() {
254	            return Err(format!(
255	                "track index {index} is out of range (0..{})",
256	                self.tracks.len()
257	            ));
258	        }
259	        if index == from {
260	            return Ok(Outcome::Identity);
261	        }
262	
263	        let mut next = self.clone();
264	        // `from` came from `track_index`, so it addresses a track that is
265	        // there; `index` was just bounds-checked against the same list.
266	        let moved = next.tracks.remove(from);
267	        next.tracks.insert(index, moved);
268	        self.finish(next)
269	    }
270	
271	    /// Sets any subset of a track's fields; an omitted argument keeps its
272	    /// value (spec §6). The name is stored trimmed, and an empty name is
273	    /// allowed — it means "unnamed", and the timeline draws the track's
274	    /// position instead. `matte` makes the track a matte for the track
275	    /// directly behind it, `none` an ordinary track again (spec §11 MT-1);
276	    /// re-choosing the current mode is an identity through `finish`, like
277	    /// every other unchanged field. `volume` (linear, 0…`TRACK_VOLUME_MAX`)
278	    /// and `pan` (−1…1) are the track's fader and balance (spec §11 AU-102);
279	    /// a value outside its range is an `Err` in `in_range`'s sentence.
280	    /// `compressor` and `limiter` (spec §11 AU-150) are read by
281	    /// `track_dynamics.rs`: `null` clears, an object replaces the whole value.
282	    #[allow(clippy::too_many_arguments)]
283	    pub fn set_track(
284	        &self,
285	        track: u32,
286	        name: Option<&str>,
287	        hidden: Option<bool>,
288	        muted: Option<bool>,
289	        locked: Option<bool>,
290	        solo: Option<bool>,
291	        matte: Option<TrackMatte>,
292	        volume: Option<f64>,
293	        pan: Option<f64>,
294	        compressor: Option<&Value>,
295	        limiter: Option<&Value>,
296	    ) -> Result<Outcome, String> {
297	        self.require_track(track)?;
298	        if let Some(volume) = volume {
299	            in_range("volume", volume, 0.0, TRACK_VOLUME_MAX)?;
300	        }
301	        if let Some(pan) = pan {
302	            in_range("pan", pan, -1.0, 1.0)?;
303	        }
304	        let compressor = compressor.map(read_compressor).transpose()?;
305	        let limiter = limiter.map(read_limiter).transpose()?;
306	        let mut next = self.clone();
307	        if let Some(found) = next.tracks.iter_mut().find(|t| t.id == track) {
308	            if let Some(name) = name {
309	                found.name = name.trim().to_string();
310	            }
311	            if let Some(hidden) = hidden {
312	                found.hidden = hidden;
313	            }
314	            if let Some(muted) = muted {
315	                found.muted = muted;
316	            }
317	            if let Some(locked) = locked {
318	                found.locked = locked;
319	            }
320	            if let Some(solo) = solo {
321	                found.solo = solo;
322	            }
323	            if let Some(matte) = matte {
324	                found.matte = matte;
325	            }
326	            if let Some(volume) = volume {
327	                found.volume = volume;
328	            }
329	            if let Some(pan) = pan {
330	                found.pan = pan;
331	            }
332	            if let Some(compressor) = compressor {
333	                found.compressor = compressor;
334	            }
335	            if let Some(limiter) = limiter {
336	                found.limiter = limiter;
337	            }
338	        }
339	        self.finish(next)
340	    }
341	
342	    /// Removes every track that holds no clips — the tidy-up after a big
343	    /// delete (spec §6).
344	    ///
345	    /// If that would empty the stack, the back-most track survives: it is
346	    /// the one a fresh project starts with, and keeping the bottom of the
347	    /// stack means the surviving track is where a drop lands.
348	    pub fn remove_empty_tracks(&self) -> Result<Outcome, String> {
349	        let mut next = self.clone();
350	        next.tracks
351	            .retain(|t| self.clips.iter().any(|c| c.track == t.id));
352	        if next.tracks.is_empty() {
353	            next.tracks = self.tracks.iter().take(1).cloned().collect();
354	        }
355	        self.finish(next)
356	    }
357	
358	    // ---- markers ---------------------------------------------------------
359	
360	    /// Adds a marker at `at`, snapped to the frame grid and clamped to 0 —
361	    /// a drag can start left of the timeline, and there is no negative time
362	    /// (spec §6).
363	    ///
364	    /// The default name is `Marker <count + 1>` and the default colour is
365	    /// `"red"`. `Err` when another marker already holds the tick: two
366	    /// markers may not share a time, and moving the existing one is the
367	    /// caller's decision, not this op's.
368	    pub fn add_marker(
369	        &self,
370	        at: Ticks,
371	        name: Option<&str>,
372	        chapter: Option<bool>,
373	        color: Option<&str>,
374	    ) -> Result<Outcome, String> {
375	        let at = self.snapped(at).max(0);

1	//! The document's canvas — spec §6, the `set_canvas` row.
2	//!
3	//! One op and the three things it has to do to the rest of the document
4	//! when it lands: check a dimension, rescale every clip's placement when
5	//! the size changes, and re-snap every stored time when the rate does.
6	//! `edit_track.rs` owns the track stack, the markers and the media list;
7	//! this file was cut out of it under the size rule and is the canvas half
8	//! of the same concern — the document's own shape rather than what sits
9	//! on it.
10	//!
11	//! The two rules worth knowing before reading:
12	//!
13	//! 1. **A canvas dimension is even**, because H.264 and HEVC encode in
14	//!    macroblocks over a chroma-subsampled plane. Catching it here makes
15	//!    it a message about the field the user just typed.
16	//! 2. **A rate change normalizes stored picture times**, so it re-snaps
17	//!    top-level and nested clips and top-level markers to the new grid — and a
18	//!    coarser grid can land two markers on one tick, which markers may
19	//!    never share.
20	
21	use crate::model::{CanvasBlending, CanvasOutput, Color, Project, VideoProps};
22	use crate::outcome::Outcome;
23	use crate::props_check::{color_ok, SCALE_MAX, SCALE_MIN};
24	use crate::time::{self, Fps, Ticks};
25	
26	/// Canvas dimension bounds. The floor is small enough for a thumbnail-sized
27	/// document and large enough that the compositor has pixels to work with;
28	/// the ceiling is past 8K, where a single frame is already 130 MB.
29	///
30	/// `pub(crate)` because `op_rows.rs`'s table publishes this range as `width`'s and
31	/// `height`'s bound: the published bound is SOURCED from the constant the
32	/// refusal below is written against, never retyped beside it.
33	pub(crate) const CANVAS_MIN: u32 = 16;
34	pub(crate) const CANVAS_MAX: u32 = 16384;
35	
36	// ---- helpers -------------------------------------------------------------
37	
38	/// A canvas dimension: inside the bounds AND even.
39	///
40	/// Even is not fussiness: H.264 and HEVC encode in macroblocks over a
41	/// chroma-subsampled plane, so an odd width or height is either refused by
42	/// the encoder or silently padded. Catching it here makes it a message
43	/// about the canvas field the user just typed instead of an export that
44	/// fails an hour later.
45	fn check_dimension(key: &str, value: u32) -> Result<(), String> {
46	    if !(CANVAS_MIN..=CANVAS_MAX).contains(&value) {
47	        return Err(format!(
48	            "{key} must be between {CANVAS_MIN} and {CANVAS_MAX}, not {value}"
49	        ));
50	    }
51	    if !value.is_multiple_of(2) {
52	        return Err(format!(
53	            "{key} must be even (h.264 encodes in macroblocks), not {value}"
54	        ));
55	    }
56	    Ok(())
57	}
58	
59	/// Multiplies every clip's placement by the canvas size ratio, so a layout
60	/// built for one canvas lands in the same relative place on the next (spec
61	/// §6, `rescale_clips`).
62	///
63	/// `x` and `y` are per-axis offsets in canvas pixels, so each follows its
64	/// OWN axis ratio — that is what keeps a layer's distance from an edge
65	/// proportional when the aspect ratio changes too. `scale` is one uniform
66	/// factor and cannot follow two ratios, so it follows the SMALLER of them:
67	/// the same `min` Fit uses, which means a layer that fitted the old canvas
68	/// still fits the new one, where the larger ratio could push it off an
69	/// edge.
70	///
71	/// Action `end` patches are deliberately NOT rescaled: a patch is opaque
72	/// JSON (`actions.rs` interprets it), and the op is defined on the clip's
73	/// props. An animated move on a resized canvas therefore keeps its old
74	/// target, which is visible and fixable, unlike a patch this function
75	/// half-understood and rewrote.
76	fn rescale(project: &mut Project, old_width: u32, old_height: u32) {
77	    if old_width == 0 || old_height == 0 {
78	        return;
79	    }
80	    let width_ratio = f64::from(project.canvas.width) / f64::from(old_width);
81	    let height_ratio = f64::from(project.canvas.height) / f64::from(old_height);
82	    if !(width_ratio.is_finite() && height_ratio.is_finite()) {
83	        return;
84	    }
85	    for clip in project.clips.iter_mut() {
86	        if let Some(video) = clip.video.as_mut() {
87	            rescale_video(video, width_ratio, height_ratio);
88	        }
89	    }
90	}
91	
92	/// One clip's placement under [`rescale`]'s rule: `x` and `y` by their own
93	/// axis's ratio, `scale` by the smaller. `reframe_clip`'s `keep` applies it
94	/// to one clip's base (spec §11 VR-26).
95	pub(crate) fn rescale_video(video: &mut VideoProps, width_ratio: f64, height_ratio: f64) {
96	    let scale_ratio = width_ratio.min(height_ratio);
97	    video.x *= width_ratio;
98	    video.y *= height_ratio;
99	    // Clamped to the same range `set_video` accepts, so a chain of
100	    // shrinks cannot leave a scale the inspector refuses to show.
101	    video.scale = (video.scale * scale_ratio).clamp(SCALE_MIN, SCALE_MAX);
102	}
103	
104	/// Re-snaps stored picture times to the canvas's CURRENT frame grid, after
105	/// that grid has changed.
106	///
107	/// Yesterday's grid is not today's: a 24 fps boundary is not a 30 fps
108	/// boundary, so top-level and stored-nest clips, their action and present
109	/// base motion/text times, and top-level markers move to the new grid.
110	///
111	/// Three clamps keep the result valid: a media clip's duration is held to
112	/// the source it still has, snapped DOWN to the new grid, so a coarser rate
113	/// cannot round a whole-file clip past the end of its file (spec §11); a
114	/// duration that would round to zero becomes one frame (a zero-length clip
115	/// is what `validate` rejects), which is the ONE case the source bound
116	/// cannot hold and `evaluate.rs`'s clamp covers; and an action is kept
117	/// inside its clip — but a ramped clip's speed action, which is snapped and
118	/// left running past the end, the duration held again (spec §11 SR-19 (g)).
119	fn resnap(project: &mut Project) {
120	    let fps = project.canvas.fps;
121	    // Temporarily own each list so source/media lookup can borrow the whole
122	    // project while a clip is normalized. Visit each stored nest exactly
123	    // once, including orphans and nests shown by more than one clip.
124	    let mut clips = std::mem::take(&mut project.clips);
125	    for clip in &mut clips {
126	        project.resnap_clip_times(clip);
127	    }
128	    project.clips = clips;
129	    for index in 0..project.nests.len() {
130	        let mut clips = std::mem::take(&mut project.nests[index].clips);
131	        for clip in &mut clips {
132	            project.resnap_clip_times(clip);
133	        }
134	        project.nests[index].clips = clips;
135	    }
136	    for marker in project.markers.iter_mut() {
137	        marker.time = time::snap_to_frame(marker.time, fps).max(0);
138	    }
139	    // A coarser grid can land two markers on one tick, which markers may
140	    // never share. The alternative — refusing a document-wide rate change
141	    // because two marks are 3 ms apart — is far worse than dropping the
142	    // second of them, so the first in the list keeps the tick.
143	    //
144	    // A linear scan over a `Vec` rather than a set: markers are capped at
145	    // 1024 and this runs only on a rate change.
146	    let mut taken: Vec<Ticks> = Vec::with_capacity(project.markers.len());
