    /// overlap rule below.
    pub fn detach_audio(&self, clip: u32) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let why = match target.source {
            Source::Media { media, .. } if !self.require_media(media)?.has_audio => {
