/// timeline's. They are the same tracks and clips — a nest is a group held
/// in the parent's one id space, and flattening one at evaluation time
/// gives its clips real composition tracks — so counting them separately
/// would let a project with 64 nests of 64 tracks past a cap that exists to
/// bound exactly that.
pub fn check_caps(p: &Project) -> Result<(), String> {
    let nested_clips: usize = p.nests.iter().map(|n| n.clips.len()).sum();
    let nested_tracks: usize = p.nests.iter().map(|n| n.tracks.len()).sum();
    let clips = p.clips.len().saturating_add(nested_clips);
    let tracks = p.tracks.len().saturating_add(nested_tracks);
    if clips > MAX_CLIPS {
        return Err(format!("too many clips: {clips} (max {MAX_CLIPS})"));
    }
    if tracks > MAX_TRACKS {
        return Err(format!("too many tracks: {tracks} (max {MAX_TRACKS})"));
    }
    /// greyed out.
    ///
    /// Nothing here is a second opinion about what those ops MEAN: the core
    /// refuses a scoped one by name either way, and an agent that asks for one
    /// with a `scope` still gets that refusal, because `scoped(_:)` above is
    /// the plain stamp and this list is consulted only by the app's own edit
    /// paths.
    static let documentLevelNames: Set<String> = [
        "add_marker", "set_marker", "remove_marker", "set_canvas", "add_media", "relink_media",
        "remove_media", "set_media_color", "set_media_speech", "set_media_cursor", "keep_range",
    ]

    /// True for one of the eleven above — an edit about the document rather
    /// than about whatever container the timeline is looking at.
    var isDocumentLevel: Bool { Self.documentLevelNames.contains(name) }
}

